style.css:
html, body {
    background-image: url("https://static.wikia.nocookie.net/sol-rng/images/a/a7/EquinoxNewCollection.gif/revision/latest?cb=20250802092429") !important;
    background-repeat: no-repeat !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    min-height: 100vh;
  }

  /* Let page elements be transparent so the background shows through */
  * {
    background-color: transparent !important;
  }

  /* Optional: remove any element shadows that might hide the background */
  * {
    box-shadow: transparent !important;
  }
